import{_ as o,l as r,o as e,c as l,v as t,p as s,x as i,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"数学归纳","description":"","frontmatter":{"title":"数学归纳","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mathematical-induction.md","filePath":"cs/mathematical-induction.md","lastUpdated":1789023840000}'),p={name:"cs/mathematical-induction.md"};function m(P,a,_,u,f,b){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="数学归纳" tabindex="-1">数学归纳 <a class="header-anchor" href="#数学归纳" aria-label="Permalink to &quot;数学归纳&quot;">​</a></h1><div class="epigraph"><p>要证明每个自然数都有某性质，只需验证 $0$，再证明「若 $n$ 有则 $n+1$ 有」。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/functions-countable">函数与可数</a>钉死了 \\(\\mathbb{N}\\) 可作编号。本课不重证可数，也不从「公理化算术」另起。缺口是：可数只说有一份清单，没有工具证明「清单上每一个都满足 \\(P\\)」。后课循环不变式、递归结构、树的性质，都要把 \\(P\\) 沿 \\(\\mathbb{N}\\) 推过去。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对有限 \\(n=5\\) 可以穷举。对所有 \\(n\\)，穷举不是证明。缺口因此不是新的集合，而是归纳法则：若 \\(P(0)\\)，且 \\(\\forall k\\,(P(k)\\Rightarrow P(k+1))\\)，则 \\(\\forall n\\,P(n)\\)。强归纳把假设加强成「小于 \\(n\\) 的都真」；对递归定义的结构（树、公式），换成结构归纳：对子对象成立则对对象成立。</p><p>本课只钉这套格式。渐近记号是下一课：归纳证明正确，不自动给出 \\(O(n^2)\\)。</p><h3 id="归纳假设不是「想当然成立」" tabindex="-1">归纳假设不是「想当然成立」 <a class="header-anchor" href="#归纳假设不是「想当然成立」" aria-label="Permalink to &quot;归纳假设不是「想当然成立」&quot;">​</a></h3><p>必须写清 \\(P(k)\\) 的语句，再在 \\(k+1\\) 的论证里<strong>调用</strong>它。只检查前几项再写「依此类推」，不是归纳。基础步选错（从 \\(1\\) 起却漏了 \\(0\\)，或树归纳漏了空树）会整棵倒掉。</p><p><span class="marginnote">Rosen 把归纳与递归定义对照：自然数、阶乘、树高。后课<a href="/cs/loop-invariant">循环不变式</a>把同一法则用在循环轮次上；本课先在 \\(\\mathbb{N}\\) 上钉格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 \\(P(n)\\)；证 \\(P(0)\\)；假设 \\(P(k)\\) 证 \\(P(k+1)\\)。对象若按大小递归定义，对定义的每条规则给一步。常见错误：在 \\(k+1\\) 步用了 \\(P(k+1)\\) 自身。</p>',11)),(e(),s(h,null,{default:i(()=>[d(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22P(0)%22%5D%20--%3E%20STEP%5B%22P(k)%20%E2%87%92%20P(k%2B1)%22%5D%0A%20%20STEP%20--%3E%20ALL%5B%22%E2%88%80n%20P(n)%22%5D%0A%20%20ALL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%B8%90%E8%BF%91%E4%B8%8E%E5%9B%BE%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>递归函数的终止与正确性用归纳：参数变小的调用对应更小的 \\(n\\)。后课图若无环，可以沿拓扑序归纳；有环则这条路断——那是<a href="/cs/tree-as-acyclic">树作为无环连通图</a>才强调的。本课不把图请进来，只把 \\(\\mathbb{N}\\) 上的梯子搭好。</p><p>归纳也能证不等式，给下一课 \\(\\Theta\\) 的具体函数比较当工具，但 \\(O\\)、\\(o\\) 的定义本身不是归纳。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入超限归纳、序数。也不把数学归纳法与「实验归纳」混名。Peano 公理的其他条（后继单射等）不展开。</p><p>后课默认：对全体自然数或全体有限树的命题，用归纳写；循环的轮次归纳是同一法则的实例。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>归纳 = 基础 + 前一步推出后一步（或全体更小）。</li><li>递归定义的对象用结构归纳。</li><li>正确性归纳不代替代价分析；渐近是下一课。</li><li>出处：Rosen, <em>Discrete Mathematics</em>。</li></ul>',8))])}const T=o(p,[["render",m]]);export{k as __pageData,T as default};
